    var CATALOG = null;
    var state = {
      screen:"welcome", lang:safeStorage.getItem("traknus-lang") || "en", theme:safeStorage.getItem("traknus-theme") || "light",
      trucks:[newTruck("Forklift 1")],
      workdayHours:8, shiftCount:1, shiftLengths:[], scheduleConfigKey:null,
      firstStart:"08:00", shiftStarts:[], breaks:[[]], intensity:"High", lift:"All"
    };
    var app = document.getElementById("app");
    function newTruck(name) {
      return {name:name,type:null,series:null,model:null,batteries:[],mode:"Standard",charger:null};
    }
    var truckColors=["#c13e45","#3276a8","#56825e","#9b65a8","#d08c32","#438b8b"];
    function tr(id,en) { return state.lang==="id" ? id : en; }
    function esc(s) { return String(s).replace(/[&<>"']/g,function(ch){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch];}); }
    function seriesOf(model) {
      var prefixes=["8FBR(S)","8FBS(S)","8FBH","8FBE","8FBN","8FBP","8FB","3TE","4CBT"];
      for(var i=0;i<prefixes.length;i++) if(model.indexOf(prefixes[i])===0) return prefixes[i];
      return model;
    }
    function typeOf(series) { return ["8FBE","8FBN","8FBH","8FB"].indexOf(series)>=0 ? "CB" : "WH"; }
    function modelsForType(type) {
      return CATALOG.models.filter(function(m){return typeOf(seriesOf(m.model))===type;});
    }
    function fmtNum(n) { return new Intl.NumberFormat(state.lang==="id"?"id-ID":"en-US",{maximumFractionDigits:1}).format(n); }
    function fmtHours(n) { return new Intl.NumberFormat(state.lang==="id"?"id-ID":"en-US",{maximumFractionDigits:2}).format(n); }
    function inputHours(n) { return String(Number(Number(n).toFixed(2))); }
    function shiftWord(n) { return state.lang==="id"?"shift":(Number(n)===1?"shift":"shifts"); }
    function fmtClock(min) {
      var m=((Math.round(min)%1440)+1440)%1440;
      return String(Math.floor(m/60)).padStart(2,"0")+":"+String(m%60).padStart(2,"0");
    }
    function toMinute(value) { var a=String(value||"08:00").split(":"); return Number(a[0])*60+Number(a[1]); }
    function removeLogoBackground() {
      var img=document.querySelector(".logo");
      function cutout() {
        if(img.dataset.cutout==="done"||!img.naturalWidth)return;
        try {
          var canvas=document.createElement("canvas");
          canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;
          var ctx=canvas.getContext("2d",{willReadFrequently:true});
          ctx.drawImage(img,0,0);
          var pixels=ctx.getImageData(0,0,canvas.width,canvas.height);
          for(var i=0;i<pixels.data.length;i+=4){
            var r=pixels.data[i],g=pixels.data[i+1],b=pixels.data[i+2];
            if(Math.min(r,g,b)>244&&Math.max(r,g,b)-Math.min(r,g,b)<14)pixels.data[i+3]=0;
          }
          ctx.putImageData(pixels,0,0);
          img.dataset.cutout="done";
          img.src=canvas.toDataURL("image/png");
        } catch(e) {
          img.dataset.cutout="unavailable";
        }
      }
      if(img.complete)cutout();else img.addEventListener("load",cutout,{once:true});
    }
    function setTheme() { document.documentElement.setAttribute("data-theme",state.theme); safeStorage.setItem("traknus-theme",state.theme); }
    function modeName(m) {
      var names={"Economy":tr("Hemat","Economy"),"Standard":tr("Standar","Standard"),"Power":tr("Daya","Power"),"High Power":tr("Daya tinggi","High Power")};
      return names[m]||m;
    }
    function intensityName(v) {
      return state.lang==="id"?({"Very Low":"Sangat rendah","Low":"Rendah","Medium":"Sedang","High":"Tinggi","Very High":"Sangat tinggi"}[v]||v):v;
    }
    function liftName(v) {
      return state.lang==="id"&&v==="All"?"Semua ketinggian":v;
    }
    function resultColor(r) { return truckColors[r.index%truckColors.length]; }
    function resultDash(r) { return ["","7 5","2 5","10 4 2 4"][Number(r.batteryIndex||0)%4]; }
    function resultDashStyle(r) { return ["solid","dashed","dotted","dashed"][Number(r.batteryIndex||0)%4]; }
    function truckSvg(type) {
      if(type==="CB") return '<svg class="truck-icon" viewBox="0 0 120 78" aria-hidden="true"><g fill="none" stroke="#cf3740" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"><path d="M14 54h58V31H40l-9 23"/><path d="M72 39h20l12 15v1H72"/><path d="M92 40V13h7v31"/><path d="M100 54h11"/><path d="M89 56h16"/><path d="M27 56a7 7 0 1 0 14 0M77 56a7 7 0 1 0 14 0"/><path d="M92 13h14M99 20h9M98 27h10"/></g><path d="M14 31h24l-5 23H14z" fill="#cf3740" opacity=".13"/></svg>';
      return '<svg class="truck-icon" viewBox="0 0 120 78" aria-hidden="true"><g fill="none" stroke="#2268a7" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 55h48V38H45L34 26H20z"/><path d="M68 47h23l12 8H68"/><path d="M22 26V13h8v42"/><path d="M30 16h22M30 24h18"/><path d="M27 57a7 7 0 1 0 14 0M76 57a7 7 0 1 0 14 0"/><path d="M100 55h9"/></g><path d="M43 28h21v10H45z" fill="#2268a7" opacity=".14"/></svg>';
    }
    function typePicker(t,slot) {
      var selected=t.type;
      return '<div class="type-grid">'+
        '<button class="type-card cb '+(selected==="CB"?"selected":"")+'" data-act="type" data-slot="'+slot+'" data-value="CB">'+truckSvg("CB")+'<span><span class="type-label">CB · Counterbalance</span><span class="type-detail">'+tr("Truk counterbalance","Counterbalance forklift")+'</span></span></button>'+
        '<button class="type-card wh '+(selected==="WH"?"selected":"")+'" data-act="type" data-slot="'+slot+'" data-value="WH">'+truckSvg("WH")+'<span><span class="type-label">WH · Warehouse</span><span class="type-detail">'+tr("Truk gudang / warehouse","Warehouse forklift")+'</span></span></button></div>';
    }
    function modePicker(t,slot) {
      var modes=[["Economy",tr("Lebih hemat energi","Lower energy use")],["Standard",tr("Pemakaian standar","Standard use")],["Power",tr("Daya kerja tinggi","Higher working power")],["High Power",tr("Daya kerja maksimal","Maximum working power")]];
      return '<div class="mode-grid">'+modes.map(function(m){return '<button class="mode-card '+(t.mode===m[0]?"selected":"")+'" data-act="mode" data-slot="'+slot+'" data-value="'+m[0]+'"><strong>'+modeName(m[0])+'</strong><span>'+m[1]+'</span></button>';}).join("")+'</div>';
    }
    function modelStep(t,slot) {
      var html="";
      if(!t.type) return '<div class="inline-note">'+tr("Pilih tipe dulu. Seri dan model baru muncul setelahnya.","Choose a truck type first. Series and model will appear next.")+'</div>';
      var avail=modelsForType(t.type);
      var seriesList=Array.from(new Set(avail.map(function(m){return seriesOf(m.model);}))).sort(function(a,b){return a.localeCompare(b,undefined,{numeric:true});});
      html+='<div class="field"><label>'+tr("2 · Pilih seri","2 · Choose a series")+'</label><div class="choice-row">'+seriesList.map(function(s){return '<button class="choice '+(t.series===s?"selected":"")+'" data-act="series" data-slot="'+slot+'" data-value="'+esc(s)+'">'+esc(s)+'</button>';}).join("")+'</div></div>';
      if(!t.series) return html;
      var same=avail.filter(function(m){return seriesOf(m.model)===t.series;});
      html+='<div class="field" style="margin-top:15px"><label>'+tr("3 · Pilih model forklift","3 · Choose a forklift model")+'</label><div class="model-grid">'+same.map(function(m){return '<button class="model-card '+(t.model===m.model?"selected":"")+'" data-act="model" data-slot="'+slot+'" data-value="'+esc(m.model)+'">'+esc(m.model)+'</button>';}).join("")+'</div></div>';
      if(!t.model) return html;
      var spec=CATALOG.models.find(function(m){return m.model===t.model;});
      var batteryOptions=spec.battery_options||[];
      html+='<div class="field" style="margin-top:15px"><label>'+tr("4 · Pilih kapasitas untuk dibandingkan","4 · Choose capacities to compare")+'</label><div class="caps">'+batteryOptions.map(function(b){var selected=t.batteries.indexOf(b.ah)>=0;return '<button class="cap '+(selected?"selected":"")+'" data-act="battery" data-slot="'+slot+'" data-value="'+b.ah+'"><span class="checkmark"></span>'+fmtNum(b.ah)+' Ah</button>';}).join("")+'</div><p class="sub" style="margin-top:7px">'+tr("Klik satu atau beberapa kapasitas. Grafik nanti membandingkan baterai yang dicentang.","Select one or more capacities. The chart will compare the checked batteries.")+'</p></div>';
      var chargers=(spec.charger_options_a||[]).map(Number).filter(function(a){return a>0;});
      html+='<div class="inline-note" style="margin-top:14px">'+(chargers.length?tr("Acuan charger pada data model: ","Charger reference in model data: ")+fmtNum(chargers[0])+" A ("+tr("ampere","amps")+"). "+tr("Arus ini dipakai saat kamu pilih Ya untuk waktu istirahat.","This current is used when you choose Yes for a break."):tr("Data arus charger tidak tercantum untuk model ini. Pilihan Ya saat istirahat tidak menambah daya pada simulasi.","Charger current is not listed for this model. Choosing Yes for a break will not add charge in the estimate."))+'</div>';
      html+='<div class="field" style="margin-top:16px"><label>'+tr("Truck Mode · pilihan di Excel","Truck mode · Excel choices")+'</label>'+modePicker(t,slot)+'</div>';
      html+='<div class="inline-note" style="margin-top:12px">'+fmtNum(spec.voltage_v)+' V · '+tr("acuan pemakaian","usage baseline")+' '+fmtNum(spec.en_ah_per_hour)+' Ah/h</div>';
      return html;
    }
    function truckPanel(index) {
      var slot="t"+(index+1), t=state.trucks[index], remove=index>0?'<button class="small-btn" data-act="remove-truck" data-index="'+index+'">− '+tr("Hapus","Remove")+'</button>':'';
      return '<section class="panel truck-box" style="--unit-color:'+truckColors[index%truckColors.length]+'"><div class="truck-box-head"><span class="truck-dot"></span><span class="truck-box-title">'+esc(t.name)+'</span><span class="sub">'+(index===0?tr("Utama","Primary"):tr("Pembanding","Compare with"))+'</span>'+remove+'</div>'+typePicker(t,slot)+'<div style="margin-top:16px">'+modelStep(t,slot)+'</div></section>';
    }
    function ensureSchedule() {
      for(var i=0;i<state.shiftCount;i++) {
        if(!Number(state.shiftLengths[i])||Number(state.shiftLengths[i])<=0) state.shiftLengths[i]=state.workdayHours/state.shiftCount;
        if(!state.breaks[i]) state.breaks[i]=[{start:null,length:defaultBreakMinutes(i),charge:false}];
        if(!state.breaks[i].length) state.breaks[i].push({start:null,length:defaultBreakMinutes(i),charge:false});
      }
      state.breaks.length=state.shiftCount;
      state.shiftStarts.length=state.shiftCount;
      state.shiftLengths.length=state.shiftCount;
    }
    function shiftLength(i) { return Number(state.shiftLengths[i]||state.workdayHours/state.shiftCount); }
    function defaultBreakMinutes(i) { return Math.max(1,Math.round(Math.min(30,shiftLength(i)*60/3)/5)*5); }
    function totalShiftHours() {
      return state.shiftLengths.slice(0,state.shiftCount).reduce(function(sum,h){return sum+Number(h||0);},0);
    }
    function shiftStart(i) {
      if(i===0) return toMinute(state.shiftStarts[0]||state.firstStart);
      var previousEnd=shiftStart(i-1)+shiftLength(i-1)*60;
      var candidate=state.shiftStarts[i]?toMinute(state.shiftStarts[i]):previousEnd;
      while(candidate<previousEnd) candidate+=1440;
      return candidate;
    }
    function breakStart(i,j) {
      var b=state.breaks[i][j];
      var start=b.start?toMinute(b.start):shiftStart(i)+Math.min(3,shiftLength(i)/2)*60;
      while(start<shiftStart(i)) start+=1440;
      return start;
    }
    function scheduleView() {
      ensureSchedule();
      var shiftCards=[];
      for(var i=0;i<state.shiftCount;i++) {
        var start=shiftStart(i), rows=state.breaks[i].map(function(b,j){
          return '<div class="break-row"><div class="break-label">'+tr("Istirahat","Break")+' '+(j+1)+'</div><div class="break-controls"><div class="field"><label>'+tr("Mulai istirahat","Break starts")+'</label><input class="input" type="time" aria-label="'+tr("Waktu mulai istirahat "+(j+1),"Break "+(j+1)+" start time")+'" data-input="break-time" data-shift="'+i+'" data-break="'+j+'" value="'+fmtClock(breakStart(i,j))+'"></div><div class="field"><label>'+tr("Durasi (menit)","Duration (minutes)")+'</label><input class="input" type="number" min="1" max="1440" step="1" aria-label="'+tr("Durasi istirahat "+(j+1)+" dalam menit","Break "+(j+1)+" duration in minutes")+'" data-input="break-length" data-shift="'+i+'" data-break="'+j+'" value="'+Number(b.length||30)+'"></div><div class="field"><label>'+tr("Forklift di-charge?","Charging during break?")+'</label><div class="charge-toggle"><button class="'+(!b.charge?"selected":"")+'" data-act="charge" data-shift="'+i+'" data-break="'+j+'" data-value="false">'+tr("Tidak","No")+'</button><button class="'+(b.charge?"selected":"")+'" data-act="charge" data-shift="'+i+'" data-break="'+j+'" data-value="true">'+tr("Ya","Yes")+'</button></div></div></div></div>';
        }).join("");
        shiftCards.push('<article class="shift-card"><div class="shift-card-head"><span class="shift-name">'+tr("Shift","Shift")+' '+(i+1)+'</span></div><div class="field-row"><div class="field"><label>'+tr("Jam mulai","Start time")+'</label><input class="input" type="time" aria-label="'+tr("Jam mulai shift "+(i+1),"Shift "+(i+1)+" start time")+'" data-input="shift-start" data-shift="'+i+'" value="'+fmtClock(start)+'"></div><div class="field"><label>'+tr("Lama shift (jam)","Shift length (hours)")+'</label><input class="input" type="number" min="0.01" max="24" step="any" aria-label="'+tr("Lama shift "+(i+1)+" dalam jam","Shift "+(i+1)+" length in hours")+'" data-input="shift-length" data-shift="'+i+'" value="'+inputHours(shiftLength(i))+'"></div></div><div class="break-section"><div class="break-section-title">'+tr("Istirahat dan charging","Break and charging")+'</div><p class="sub">'+tr("Atur waktu dan durasi istirahat dalam menit. Pilih Ya hanya jika forklift di-charge selama jeda ini.","Set the break time and duration in minutes. Choose Yes only if the forklift is charging during this break.")+'</p><div class="break-list">'+rows+'</div><button class="small-btn" style="margin-top:10px" data-act="add-break" data-shift="'+i+'">+ '+tr("Tambah istirahat","Add a break")+'</button></div></article>');
      }
      return '<div class="schedule-grid">'+shiftCards.join("")+'</div>';
    }
    function progressView(active) {
      var labels=[tr("Kondisi kerja","Working conditions"),tr("Jadwal shift","Shift schedule"),tr("Pilih forklift","Choose forklift"),tr("Analisis","Analysis")];
      return '<div class="progress">'+labels.map(function(label,i){return '<span class="step '+(i<active?"active":"")+'"><span class="step-num">'+(i+1)+'</span>'+label+'</span>'+(i<labels.length-1?'<span class="progress-line"></span>':'');}).join("")+'</div>';
    }
    function conditionsScreen() {
      var perShift=state.workdayHours/state.shiftCount;
      var html=progressView(1);
      html+='<section class="panel"><div class="panel-head"><div><div class="eyebrow-small">'+tr("Working Conditions","Working conditions")+'</div><h2>'+tr("Tentukan jam operasi dan jumlah shift","Set operating hours and shifts")+'</h2><p class="sub">'+tr("Masukkan total waktu operasi forklift dalam sehari. Setelah dikonfirmasi, waktu ini dibagi rata sebagai nilai awal tiap shift.","Enter the total forklift operating hours per day. After confirmation, this time is divided evenly as the starting length for each shift.")+'</p></div></div><div class="two-col"><div class="field"><label>'+tr("Lama kerja per hari (jam)","Workday length (hours per day)")+'</label><input class="input" style="max-width:220px" type="number" min="1" max="24" step="0.5" data-input="workday-hours" value="'+state.workdayHours+'"></div><div class="field"><label>'+tr("Jumlah shift per hari","Number of shifts per day")+'</label><div class="count-control"><button class="small-btn" type="button" data-act="shift-minus" aria-label="'+tr("Kurangi shift","Decrease shifts")+'">−</button><input class="input" type="number" min="1" max="24" step="1" data-input="shift-count" value="'+state.shiftCount+'" aria-label="'+tr("Jumlah shift","Number of shifts")+'"><button class="small-btn" type="button" data-act="shift-plus" aria-label="'+tr("Tambah shift","Increase shifts")+'">+</button></div><p class="sub" style="margin-top:6px">'+tr("Bisa ketik langsung jumlah shift yang dibutuhkan.","Type the number of shifts you need.")+'</p></div></div><div class="inline-note" style="margin-top:16px">'+tr("Nilai awal: ","Starting point: ")+fmtHours(state.workdayHours)+' '+tr("jam per hari dibagi","hours per day divided across")+' '+state.shiftCount+' '+shiftWord(state.shiftCount)+', '+tr("sekitar","about")+' '+fmtHours(perShift)+' '+tr("jam per shift. Durasi dapat diubah setelah konfirmasi.","hours per shift. You can edit each duration after confirming.")+'</div><div class="button-row"><span class="sub">'+tr("Waktu mulai dan break diatur setelah langkah ini.","Start times and breaks are set after this step.")+'</span><button class="primary" data-act="confirm-conditions">'+tr("Confirm · atur jadwal shift","Confirm · set shift schedule")+' →</button></div></section>';
      return html;
    }
    function scheduleScreen() {
      var total=totalShiftHours(), balanced=Math.abs(total-state.workdayHours)<0.02;
      var html=progressView(2);
      html+='<section class="panel"><div class="panel-head"><div><div class="eyebrow-small">'+tr("Shift schedule","Shift schedule")+'</div><h2>'+tr("Atur waktu tiap shift","Set each shift’s timing")+'</h2><p class="sub">'+tr("Setiap shift memiliki jam mulai, lama kerja, dan setidaknya satu waktu istirahat. Jam shift berikutnya otomatis mengikuti shift sebelumnya, lalu bisa kamu ubah.","Each shift has a start time, work length, and at least one break. The next shift starts after the previous one by default; you can edit it.")+'</p></div></div><div class="stat-grid"><article class="stat"><div class="stat-label">'+tr("Target jam kerja harian","Daily workday target")+'</div><div class="stat-value">'+fmtHours(state.workdayHours)+' '+tr("jam","hours")+'</div></article><article class="stat"><div class="stat-label">'+tr("Total lama semua shift","Total scheduled shift hours")+'</div><div class="stat-value">'+fmtHours(total)+' '+tr("jam","hours")+'</div></article></div>'+scheduleView()+(balanced?'<div class="green-box">'+tr("Total durasi shift sesuai target harian.","Shift lengths match the daily target.")+'</div>':'<div class="alert-box">'+tr("Total durasi shift berbeda dari target harian. Kamu tetap bisa lanjut atau sesuaikan lama tiap shift.","Shift lengths differ from the daily target. You can continue or adjust individual shift lengths.")+'</div>')+'<div class="button-row"><button class="secondary" data-act="back-conditions">← '+tr("Ubah Working Conditions","Edit working conditions")+'</button><button class="primary" data-act="continue-trucks">'+tr("Lanjut pilih forklift","Continue to forklift selection")+' →</button></div></section>';
      return html;
    }
    function truckScreen() {
      var html=progressView(3);
      html+='<section class="panel"><div class="panel-head"><div><div class="eyebrow-small">'+tr("Truck setup","Truck setup")+'</div><h2>'+tr("Pilih forklift yang mau diuji","Choose the forklift to simulate")+'</h2><p class="sub">'+tr("Pilih tipe, seri, model, kapasitas baterai, dan Truck Mode.","Choose the type, series, model, battery capacity, and truck mode.")+'</p><p class="info-pill">'+fmtHours(state.workdayHours)+' '+tr("jam/hari","hours/day")+' · '+state.shiftCount+' '+shiftWord(state.shiftCount)+'</p></div></div>';
      for(var i=0;i<state.trucks.length;i++) html+=truckPanel(i);
      html+='<div class="button-row"><button class="secondary add-truck-btn" data-act="add-truck" '+(state.trucks.length>=6?'disabled':'')+'>+ '+tr("Tambah forklift pembanding","Add another forklift")+'</button><span class="sub">'+tr("Pilih sampai 6 forklift. Semua hasil tampil bersama di grafik.","Compare up to 6 forklifts on one chart.")+'</span></div></section>';
      html+='<div class="button-row"><button class="secondary" data-act="back-schedule">← '+tr("Kembali ke jadwal shift","Back to shift schedule")+'</button><button class="primary" data-act="analyze">'+tr("Tampilkan analisis baterai →","Show battery analysis →")+'</button></div>';
      return html;
    }
    function welcomeScreen() {
      return '<section class="panel welcome-panel"><h2 class="welcome-title">'+tr("Mulai dari forklift dan jadwal kerjamu.","Start with your forklift and work schedule.")+'</h2><p class="sub">'+tr("Bandingkan pilihan kapasitas baterai, lihat perkiraan sisa baterai sepanjang shift, lalu simpan hasilnya sebagai PDF.","Compare battery capacities, follow the estimated battery level through your shifts, and save a clear PDF report.")+'</p><div class="welcome-steps"><div class="welcome-step"><span class="welcome-step-number">1</span><strong>'+tr("Kondisi kerja","Working conditions")+'</strong><span>'+tr("Tentukan jam operasi harian dan jumlah shift.","Set daily operating hours and the number of shifts.")+'</span></div><div class="welcome-step"><span class="welcome-step-number">2</span><strong>'+tr("Jadwal shift","Shift schedule")+'</strong><span>'+tr("Isi waktu mulai, durasi, istirahat, dan charging.","Set start times, duration, breaks, and charging.")+'</span></div><div class="welcome-step"><span class="welcome-step-number">3</span><strong>'+tr("Pilih forklift","Choose a forklift")+'</strong><span>'+tr("Tentukan model, mode kerja, dan kapasitas baterai.","Choose the model, operating mode, and battery capacity.")+'</span></div><div class="welcome-step"><span class="welcome-step-number">4</span><strong>'+tr("Lihat dan cetak","View and print")+'</strong><span>'+tr("Baca grafik dan cetak ringkasan sebagai PDF.","Review the chart and print the report as a PDF.")+'</span></div></div><button class="primary" data-act="start">'+tr("Mulai simulasi","Start simulation")+' →</button></section>';
    }
    function allConfigs() {
      return state.trucks.map(function(t,index){
        var spec=CATALOG.models.find(function(m){return m.model===t.model;});
        return {truck:t,spec:spec,index:index};
      }).filter(function(c){return c.truck.model&&c.spec;});
    }
    function simulate(config,battery) {
      var t=config.truck,spec=config.spec;
      var usable=battery.ah*(1-(battery.reserve_pct||0));
      var modeFactor=Number((spec.power_modes||{})[t.mode]||1);
      var draw=spec.en_ah_per_hour*modeFactor*CATALOG.intensity_factors[state.intensity]*CATALOG.lift_factors[state.lift];
      var charger=Number(t.charger===null?((spec.charger_options_a||[])[0]||0):t.charger);
      var chargeRate=Math.min(Number(battery.ah),charger)*Number(CATALOG.charge_efficiency||1);
      var windows=[];
      for(var i=0;i<state.shiftCount;i++) {
        var start=shiftStart(i);
        var end=start+shiftLength(i)*60;
        windows.push({start:start,end:end,shift:i});
      }
      var first=windows[0].start,last=windows.reduce(function(a,w){return Math.max(a,w.end);},0),step=Number(CATALOG.time_step_min||5);
      var breaks=[];
      for(var si=0;si<windows.length;si++) {
        var w=windows[si];
        state.breaks[si].forEach(function(b,j){
          var bs=breakStart(si,j);
          while(bs<w.start) bs+=1440;
          var len=Number(b.length||0);
          if(len>0) breaks.push({start:bs,end:bs+len,charge:!!b.charge});
        });
      }
      var timeline=[first];
      for(var m=first+step;m<last;m+=step) timeline.push(m);
      if(timeline[timeline.length-1]<last) timeline.push(last);
      var soc=usable,points=[];
      for(var p=0;p<timeline.length;p++) {
        var minute=timeline[p];
        if(p>0) {
          var pm=timeline[p-1],elapsed=(minute-pm)/60;
          var working=windows.some(function(w){return w.start<=pm&&pm<w.end;});
          var br=null;
          for(var bi=0;bi<breaks.length;bi++) if(breaks[bi].start<=pm&&pm<breaks[bi].end){br=breaks[bi];break;}
          if(working&&br===null) soc-=draw*elapsed;
          else if(working&&br&&br.charge&&chargeRate>0) soc+=chargeRate*elapsed;
          soc=Math.max(0,Math.min(usable,soc));
        }
        points.push({elapsed:(minute-first)/60,clock:fmtClock(minute),soc:usable?soc/usable*100:0,minute:minute});
      }
      var min=points.reduce(function(a,p){return Math.min(a,p.soc);},100),end=points[points.length-1].soc;
      var threshold=Number(CATALOG.soft_safety_pct||.10)*100;
      var soft=points.find(function(p){return p.soc<=threshold;});
      return {label:t.name+" · "+spec.model+" · "+fmtNum(battery.ah)+" Ah",truckName:t.name,model:spec.model,truckType:t.type,points:points,draw:draw,usable:usable,runtime:draw?usable/draw:0,min:min,end:end,chargeRate:chargeRate,threshold:threshold,soft:soft?soft.elapsed:null,depleted:min<=.01,battery:battery,index:config.index};
    }
    function chartSvg(results,forPrint) {
      var W=840,H=360,L=58,R=20,T=18,B=48,iw=W-L-R,ih=H-T-B;
      var max=0;
      for(var i=0;i<results.length;i++) max=Math.max(max,results[i].points[results[i].points.length-1].elapsed);
      max=Math.max(max,.25);
      var x=function(v){return L+iw*v/max;}, y=function(v){return T+ih*(100-v)/100;};
      var ink=forPrint?"#586a73":getComputedStyle(document.documentElement).getPropertyValue("--muted").trim();
      var line=forPrint?"#d8e0e0":getComputedStyle(document.documentElement).getPropertyValue("--line").trim();
      var parts=['<svg class="chart" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="'+tr("Grafik persentase sisa baterai sepanjang jadwal","Battery remaining percentage over the work schedule")+'">'];
      ensureSchedule();
      var base=shiftStart(0);
      for(var si=0;si<state.shiftCount;si++) state.breaks[si].forEach(function(b,j){
        var start=breakStart(si,j);
        while(start<shiftStart(si)) start+=1440;
        var elapsed=(start-base)/60,duration=Number(b.length||0)/60,end=elapsed+duration;
        if(duration<=0||end<=0||elapsed>=max)return;
        var x0=x(Math.max(0,elapsed)),x1=x(Math.min(max,end));
        if(x1-x0<1)return;
        var fill=b.charge?"#347b65":"#929fa3";
        var title=tr("Shift ","Shift ")+(si+1)+" · "+fmtClock(start)+"–"+fmtClock(start+Number(b.length||0))+" · "+(b.charge?tr("charging","charging"):tr("tidak charging","not charging"));
        parts.push('<g><title>'+esc(title)+'</title><rect x="'+x0.toFixed(1)+'" y="'+T+'" width="'+(x1-x0).toFixed(1)+'" height="'+ih+'" rx="3" fill="'+fill+'" opacity=".16"/></g>');
      });
      for(var v=0;v<=100;v+=5){
        var major=v%10===0;
        parts.push('<line x1="'+L+'" y1="'+y(v)+'" x2="'+(W-R)+'" y2="'+y(v)+'" stroke="'+line+'" stroke-width="'+(major?"1":".7")+'" opacity="'+(major?".7":".34")+'"/><text x="'+(L-9)+'" y="'+(y(v)+3.5)+'" text-anchor="end" fill="'+ink+'" font-size="10">'+v+'%</text>');
      }
      var wholeHours=Math.floor(max+1e-9),fractionalEnd=max-wholeHours>1e-6;
      var tightEnd=fractionalEnd&&x(max)-x(wholeHours)<44;
      for(var hour=0;hour<=wholeHours;hour++){
        var ev=hour,clock=fmtClock(base+ev*60),labelY=tightEnd&&hour===wholeHours?H-31:H-17;
        parts.push('<line x1="'+x(ev)+'" y1="'+T+'" x2="'+x(ev)+'" y2="'+(H-B)+'" stroke="'+line+'" stroke-width="1" opacity=".42"/><text x="'+x(ev)+'" y="'+labelY+'" text-anchor="middle" fill="'+ink+'" font-size="10">'+clock+'</text>');
      }
      if(fractionalEnd){
        var endClock=fmtClock(base+max*60);
        parts.push('<line x1="'+x(max)+'" y1="'+T+'" x2="'+x(max)+'" y2="'+(H-B)+'" stroke="'+line+'" stroke-width="1" opacity=".58"/><text x="'+x(max)+'" y="'+(H-17)+'" text-anchor="middle" fill="'+ink+'" font-size="10">'+endClock+'</text>');
      }
      results.forEach(function(r,idx){
        var color=resultColor(r),d=resultDash(r);
        var path=r.points.map(function(p,j){return (j?"L":"M")+x(p.elapsed).toFixed(1)+" "+y(p.soc).toFixed(1);}).join(" ");
        parts.push('<path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="3.2" stroke-linejoin="round" stroke-linecap="round" '+(d?'stroke-dasharray="'+d+'"':'')+'/>');
        var last=r.points[r.points.length-1];
        parts.push('<circle cx="'+x(last.elapsed)+'" cy="'+y(last.soc)+'" r="4.5" fill="'+color+'" stroke="var(--panel)" stroke-width="2"/>');
      });
      parts.push('</svg>');
      return parts.join("");
    }
    function breakTimeline() {
      ensureSchedule();
      var chips=[];
      for(var i=0;i<state.shiftCount;i++) state.breaks[i].forEach(function(b,j){
        var start=breakStart(i,j);
        while(start<shiftStart(i)) start+=1440;
        var end=start+Number(b.length||0);
        var label=tr("Shift ","Shift ")+(i+1)+" · "+fmtClock(start)+"–"+fmtClock(end)+" · "+(b.charge?tr("Charging","Charging"):tr("Tidak charging","Not charging"));
        chips.push('<span class="break-time-chip '+(b.charge?"charging":"")+'"><span class="break-swatch" aria-hidden="true"></span>'+esc(label)+'</span>');
      });
      return '<div class="break-timeline"><div class="break-timeline-title">'+tr("Waktu istirahat di grafik","Break times shown on chart")+'</div>'+chips.join("")+'</div>';
    }
    function reportSummary(configs) {
      var shiftRows=[];
      for(var i=0;i<state.shiftCount;i++) {
        var breaks=state.breaks[i].map(function(b,j){
          return tr("Istirahat ","Break ")+(j+1)+" · "+fmtClock(breakStart(i,j))+" · "+Number(b.length||0)+" "+tr("menit","min")+" · "+(b.charge?tr("Charging","Charging"):tr("Tidak charging","Not charging"));
        }).join("<br>");
        shiftRows.push("<tr><td>"+tr("Shift ","Shift ")+(i+1)+"</td><td>"+fmtClock(shiftStart(i))+"</td><td>"+fmtHours(shiftLength(i))+" "+tr("jam","h")+"</td><td>"+breaks+"</td></tr>");
      }
      var truckRows=configs.map(function(c){
        var t=c.truck,spec=c.spec;
        var selected=(spec.battery_options||[]).filter(function(b){return t.batteries.indexOf(b.ah)>=0;}).map(function(b){return fmtNum(b.ah)+" Ah";}).join(", ");
        var charger=Number(t.charger===null?((spec.charger_options_a||[])[0]||0):t.charger);
        var chargerText=charger?fmtNum(charger)+" A":tr("Tidak tercantum","Not listed");
        return "<tr><td>"+esc(t.name)+"</td><td>"+esc(t.type||"")+" · "+esc(spec.model)+"</td><td>"+esc(modeName(t.mode))+"</td><td>"+esc(selected)+"</td><td>"+chargerText+"</td></tr>";
      });
      return '<section class="panel report-summary"><div class="panel-head"><div><h2>'+tr("Ringkasan konfigurasi","Simulation details")+'</h2><p class="sub">'+tr("Jadwal dan pilihan forklift yang ikut disimpan di laporan.","Shift schedule and forklift choices included in the report.")+'</p></div></div><div class="stat-grid"><article class="stat"><div class="stat-label">'+tr("Target jam kerja harian","Daily workday target")+'</div><div class="stat-value">'+fmtHours(state.workdayHours)+' '+tr("jam","hours")+'</div></article><article class="stat"><div class="stat-label">'+tr("Total durasi shift","Total shift hours")+'</div><div class="stat-value">'+fmtHours(totalShiftHours())+' '+tr("jam","hours")+'</div></article><article class="stat"><div class="stat-label">'+tr("Work Intensity","Work intensity")+'</div><div class="stat-value">'+esc(intensityName(state.intensity))+'</div></article><article class="stat"><div class="stat-label">'+tr("Lift Height","Lift height")+'</div><div class="stat-value">'+esc(liftName(state.lift))+'</div></article></div><h3>'+tr("Jadwal shift dan break","Shift and break schedule")+'</h3><div class="report-table-wrap"><table class="report-table"><thead><tr><th>'+tr("Shift","Shift")+'</th><th>'+tr("Mulai","Start")+'</th><th>'+tr("Lama kerja","Work length")+'</th><th>'+tr("Break dan charging","Break and charging")+'</th></tr></thead><tbody>'+shiftRows.join("")+'</tbody></table></div><h3 style="margin-top:18px">'+tr("Forklift dan baterai","Forklift and battery")+'</h3><div class="report-table-wrap"><table class="report-table"><thead><tr><th>'+tr("Unit","Unit")+'</th><th>'+tr("Tipe dan model","Type and model")+'</th><th>'+tr("Truck Mode","Truck mode")+'</th><th>'+tr("Kapasitas","Capacities")+'</th><th>'+tr("Acuan charger","Charger ref.")+'</th></tr></thead><tbody>'+truckRows.join("")+'</tbody></table></div></section>';
    }
    function printReport(configs,results) {
      var generatedAt=new Date(),locale=state.lang==="id"?"id-ID":"en-GB",date=new Intl.DateTimeFormat(locale,{day:"numeric",month:"long",year:"numeric"}).format(generatedAt),time=new Intl.DateTimeFormat(locale,{hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}).format(generatedAt);
      var shiftRows=[];
      for(var i=0;i<state.shiftCount;i++) {
        var breaks=state.breaks[i].map(function(b,j){return fmtClock(breakStart(i,j))+" · "+Number(b.length||0)+" "+tr("menit","min")+" · "+(b.charge?tr("Charging","Charging"):tr("Tidak charging","Not charging"));}).join("<br>");
        shiftRows.push("<tr><td>"+(i+1)+"</td><td>"+fmtClock(shiftStart(i))+"</td><td>"+fmtHours(shiftLength(i))+" "+tr("jam","hours")+"</td><td>"+breaks+"</td></tr>");
      }
      var resultRows=results.map(function(r){
        var unit=configs.find(function(c){return c.index===r.index;});
        return "<tr><td>"+esc(r.truckName)+" · "+esc(r.truckType)+" · "+esc(r.model)+"</td><td>"+esc(modeName(unit.truck.mode))+"</td><td>"+fmtNum(r.battery.ah)+" Ah</td><td><strong>"+fmtNum(r.end)+"%</strong></td><td>"+fmtNum(r.runtime)+" "+tr("jam","hours")+"</td></tr>";
      }).join("");
      return '<article class="print-report"><header class="print-header"><img class="print-logo" src="data:image/png;base64," alt="Traknus"><div class="print-date">'+tr("Tanggal & waktu simulasi","Simulation date & time")+'<br><strong>'+date+' · '+time+'</strong></div></header><h1>'+tr("Estimasi waktu operasional baterai","Battery runtime estimate")+'</h1><p class="print-lead">'+tr("Ringkasan berdasarkan forklift, baterai, dan jadwal kerja yang dipilih.","Summary based on the selected forklifts, batteries, and work schedule.")+'</p><section><h2>'+tr("Kondisi operasi","Operating conditions")+'</h2><div class="print-facts"><div class="print-fact"><span>'+tr("Jam operasi per hari","Operating hours per day")+'</span><strong>'+fmtHours(state.workdayHours)+' '+tr("jam","hours")+'</strong></div><div class="print-fact"><span>'+tr("Jumlah shift","Number of shifts")+'</span><strong>'+state.shiftCount+'</strong></div><div class="print-fact"><span>'+tr("Intensitas kerja","Work intensity")+'</span><strong>'+esc(intensityName(state.intensity))+'</strong></div><div class="print-fact"><span>'+tr("Tinggi angkat","Lift height")+'</span><strong>'+esc(liftName(state.lift))+'</strong></div></div></section><section><h2>'+tr("Jadwal shift dan istirahat","Shift and break schedule")+'</h2><table class="print-table"><thead><tr><th>'+tr("Shift","Shift")+'</th><th>'+tr("Mulai","Start")+'</th><th>'+tr("Durasi","Duration")+'</th><th>'+tr("Istirahat dan charging","Break and charging")+'</th></tr></thead><tbody>'+shiftRows.join("")+'</tbody></table></section><section><h2>'+tr("Perbandingan forklift dan baterai","Forklift and battery comparison")+'</h2><table class="print-table"><thead><tr><th>'+tr("Forklift / model","Forklift / model")+'</th><th>'+tr("Truck Mode","Truck mode")+'</th><th>'+tr("Baterai","Battery")+'</th><th>'+tr("Sisa setelah jadwal","Remaining after schedule")+'</th><th>'+tr("Waktu jalan terus-menerus*","Continuous runtime*")+'</th></tr></thead><tbody>'+resultRows+'</tbody></table></section><section class="print-chart"><h2>'+tr("Sisa baterai sepanjang jadwal","Battery level through the schedule")+'</h2><div class="chart-wrap">'+chartSvg(results,true)+'</div><div class="legend">'+results.map(function(r){return '<div class="legend-item"><span class="legend-line" style="border-color:'+resultColor(r)+';border-top-style:'+resultDashStyle(r)+'"></span>'+esc(r.label)+'</div>';}).join("")+'</div>'+breakTimeline()+'</section><p class="print-note">* '+tr("Waktu jalan terus-menerus adalah perkiraan bila forklift bekerja tanpa istirahat atau charging. Persentase sisa di atas memperhitungkan jadwal istirahat dan charging yang dimasukkan. Hasil aktual dapat berbeda sesuai kondisi lapangan.","Continuous runtime estimates uninterrupted work without breaks or charging. The remaining percentage reflects the breaks and charging entered above. Actual results may vary with operating conditions.")+'</p></article>';
    }
    function analysisScreen() {
      var configs=allConfigs(), results=[];
      configs.forEach(function(c){
        var selected=(c.spec.battery_options||[]).filter(function(b){return c.truck.batteries.indexOf(b.ah)>=0;});
        selected.forEach(function(b,batteryIndex){var result=simulate(c,b);result.batteryIndex=batteryIndex;results.push(result);});
      });
      var html=progressView(4);
      html+='<div class="button-row" style="margin:0 0 14px"><div><div class="eyebrow-small">'+tr("Analisis operasional","Operating analysis")+'</div><h2 style="margin:0;font-size:1.45rem">'+tr("Lihat perubahan sisa baterai","See the battery level change")+'</h2></div><button class="secondary" data-act="start-over">↺ '+tr("Kembali ke awal","Return to start")+'</button></div>';
      html+='<section class="panel"><div class="panel-head"><div><h2>'+tr("Kondisi kerja untuk grafik","Work conditions for the chart")+'</h2><p class="sub">'+tr("Pilih kondisi kerja; grafik sisa baterai langsung diperbarui.","Choose the work conditions; the battery remaining graph updates immediately.")+'</p></div><span class="info-pill">'+tr("Sisa baterai · %","Battery remaining · %")+'</span></div><div class="conditions"><div class="condition-box"><h3>'+tr("Work Intensity","Work intensity")+'</h3><p class="sub">'+tr("Seberapa berat pola penggunaan truk.","How demanding the truck usage is.")+'</p><div class="choice-row">'+Object.keys(CATALOG.intensity_factors).map(function(v){return '<button class="choice '+(state.intensity===v?"selected":"")+'" data-act="intensity" data-value="'+esc(v)+'">'+esc(intensityName(v))+'</button>';}).join("")+'</div></div><div class="condition-box"><h3>'+tr("Lift Height","Lift height")+'</h3><p class="sub">'+tr("Pilih rentang tinggi angkat yang sesuai.","Choose the matching lifting-height range.")+'</p><div class="choice-row">'+Object.keys(CATALOG.lift_factors).map(function(v){return '<button class="choice '+(state.lift===v?"selected":"")+'" data-act="lift" data-value="'+esc(v)+'">'+esc(liftName(v))+'</button>';}).join("")+'</div></div></div></section>';
      if(!results.length) return html+'<section class="panel"><div class="inline-note">'+tr("Belum ada kapasitas yang dipilih. Kembali dan pilih minimal satu baterai.","No battery capacity selected. Go back and select at least one battery.")+'</div></section>';
      html+=reportSummary(configs);
      html+='<section class="panel"><div class="panel-head"><div><h2><strong>'+tr("Visualisasi","Visualization")+'</strong> · '+tr("Sisa baterai sepanjang jadwal","Battery remaining through the schedule")+'</h2><p class="sub">'+tr("Perkiraan sisa baterai dari awal hingga akhir jadwal kerja.","Estimated battery remaining from the start to the end of the work schedule.")+'</p></div><span class="info-pill">'+state.shiftCount+' '+shiftWord(state.shiftCount)+' · '+fmtHours(state.workdayHours)+' '+tr("jam/hari","hours/day")+'</span></div>';
      html+='<div class="chart-wrap">'+chartSvg(results)+'</div><p class="chart-scroll-note">'+tr("Geser grafik ke samping untuk melihat semua jam.","Swipe the chart sideways to see all hours.")+'</p><div class="legend">'+results.map(function(r){return '<div class="legend-item"><span class="legend-line" style="border-color:'+resultColor(r)+';border-top-style:'+resultDashStyle(r)+'"></span>'+esc(r.label)+'</div>';}).join("")+'</div>';
      html+='<p class="chart-caption">'+tr("Warna garis menandai forklift; pola garis membedakan kapasitas baterai.","Line colors identify forklifts; line patterns distinguish battery capacities.")+'</p>'+breakTimeline()+'</section>';
      html+='<section class="panel"><div class="panel-head"><div><h2>'+tr("Ringkasan tiap pilihan baterai","Summary for each battery option")+'</h2><p class="sub">'+tr("Lihat sisa baterai di akhir jadwal dan perkiraan waktu kerja nonstop.","See the remaining battery at the end of the schedule and estimated nonstop runtime.")+'</p></div></div><div class="stat-grid">'+results.map(function(r){return '<article class="stat"><div class="stat-label">'+esc(r.label)+'</div><div class="stat-value">'+fmtNum(r.end)+'% <span style="font-size:.72rem;color:var(--muted)">'+tr("Sisa di akhir jadwal","remaining after schedule")+'</span></div><div class="sub" style="margin-top:6px">'+tr("Perkiraan kerja nonstop*","Estimated nonstop runtime*")+': <strong>'+fmtNum(r.runtime)+' '+tr("jam","hours")+'</strong></div></article>';}).join("")+'</div><p class="chart-caption">* '+tr("Perkiraan kerja nonstop tidak menghitung waktu istirahat atau charging.","Nonstop runtime does not include breaks or charging.")+'</p>';
      var low=results.some(function(r){return r.depleted||r.end<r.threshold;});
      if(low) html+='<div class="alert-box">'+tr("Ada pilihan baterai yang mencapai batas rendah sebelum jadwal selesai. Coba kapasitas lebih besar, kurangi intensitas, atau tambahkan charging saat istirahat.","At least one battery option reaches a low level before the schedule ends. Try a larger capacity, lower intensity, or charging during a break.")+'</div>';
      html+='<div class="button-row"><div><div class="sub">'+tr("Estimasi mengikuti faktor dari data model; kondisi lapangan dapat berbeda.","Estimates follow the model data; actual results may vary with operating conditions.")+'</div><div class="print-hint">'+tr("Pilih “Simpan sebagai PDF” pada jendela cetak.","Choose “Save as PDF” in the print window.")+'</div></div><div class="button-group"><button class="secondary" data-act="back-trucks">← '+tr("Ubah pilihan forklift","Edit forklift choices")+'</button><button class="primary" data-act="print">⌑ '+tr("Cetak / simpan PDF","Print / save PDF")+'</button></div></div></section>';
      html+=printReport(configs,results);
      return html;
    }
    function render() {
      setTheme();
      document.documentElement.lang=state.lang;
      document.getElementById("heroTitle").textContent=state.screen==="welcome"?tr("Perkirakan waktu kerja baterai","Estimate battery runtime"):tr("Simulator Waktu Operasional Baterai","Battery Runtime Simulator");
      document.getElementById("heroSub").textContent=state.screen==="welcome"?tr("Rencanakan baterai forklift dengan jadwal kerja yang mudah dipahami.","Plan forklift batteries with an easy-to-understand work schedule."):tr("Lihat perkiraan baterai untuk truk dan jadwal kerja yang kamu pilih.","Estimate battery runtime for your selected forklift and work schedule.");
      document.querySelectorAll(".language-switch [data-lang]").forEach(function(button){button.setAttribute("aria-pressed",String(button.dataset.lang===state.lang));});
      document.getElementById("themeButton").textContent=state.theme==="dark"?"☼":"◐";
      document.getElementById("themeButton").setAttribute("aria-label",tr("Ganti tema","Toggle color theme"));
      app.innerHTML=state.screen==="welcome"?welcomeScreen():
        (state.screen==="conditions"?conditionsScreen():
        (state.screen==="schedule"?scheduleScreen():
        (state.screen==="trucks"?truckScreen():analysisScreen())));
    }
    function validSetup() {
      var configs=state.trucks;
      for(var i=0;i<configs.length;i++){
        if(!configs[i].type||!configs[i].series||!configs[i].model) return tr("Lengkapi tipe, seri, dan model truk.","Complete the truck type, series, and model.");
        if(!configs[i].batteries.length) return tr("Pilih minimal satu kapasitas baterai.","Select at least one battery capacity.");
      }
      return "";
    }
    app.addEventListener("click",function(e){
      var b=e.target.closest("[data-act]"); if(!b) return;
      var act=b.dataset.act,slot=b.dataset.slot,index=slot?Number(slot.slice(1))-1:0,t=state.trucks[index]||state.trucks[0];
      if(act==="type"){t.type=b.dataset.value;t.series=null;t.model=null;t.batteries=[];t.charger=null;t.mode="Standard";}
      else if(act==="series"){t.series=b.dataset.value;t.model=null;t.batteries=[];t.charger=null;}
      else if(act==="model"){t.model=b.dataset.value;var spec=CATALOG.models.find(function(m){return m.model===t.model;});t.batteries=(spec.battery_options||[]).map(function(x){return x.ah;});t.charger=(spec.charger_options_a||[])[0]||0;if(!Object.keys(spec.power_modes||{}).includes(t.mode))t.mode="Standard";}
      else if(act==="battery"){var ah=Number(b.dataset.value);t.batteries=t.batteries.indexOf(ah)>=0?t.batteries.filter(function(x){return x!==ah;}):t.batteries.concat([ah]);}
      else if(act==="charger")t.charger=Number(b.dataset.value);
      else if(act==="mode")t.mode=b.dataset.value;
      else if(act==="add-truck"){if(state.trucks.length<6)state.trucks.push(newTruck("Forklift "+(state.trucks.length+1)));}
      else if(act==="remove-truck"){var removeIndex=Number(b.dataset.index);if(removeIndex>0&&removeIndex<state.trucks.length){state.trucks.splice(removeIndex,1);state.trucks.forEach(function(unit,i){unit.name="Forklift "+(i+1);});}}
      else if(act==="start")state.screen="conditions";
      else if(act==="shift-minus")state.shiftCount=Math.max(1,state.shiftCount-1);
      else if(act==="shift-plus")state.shiftCount=Math.min(24,state.shiftCount+1);
      else if(act==="confirm-conditions"){
        var configKey=Number(state.workdayHours).toFixed(3)+"|"+state.shiftCount;
        if(state.scheduleConfigKey!==configKey){
          state.shiftLengths=Array.from({length:state.shiftCount},function(){return state.workdayHours/state.shiftCount;});
          state.shiftStarts=[];state.breaks=[];state.firstStart="08:00";state.scheduleConfigKey=configKey;
        }
        ensureSchedule();state.screen="schedule";
      }
      else if(act==="continue-trucks")state.screen="trucks";
      else if(act==="back-conditions")state.screen="conditions";
      else if(act==="back-schedule")state.screen="schedule";
      else if(act==="back-trucks")state.screen="trucks";
      else if(act==="add-break"){var si=Number(b.dataset.shift);state.breaks[si].push({start:null,length:defaultBreakMinutes(si),charge:false});}
      else if(act==="charge"){var si=Number(b.dataset.shift),bi=Number(b.dataset.break);state.breaks[si][bi].charge=b.dataset.value==="true";}
      else if(act==="intensity")state.intensity=b.dataset.value;
      else if(act==="lift")state.lift=b.dataset.value;
      else if(act==="start-over"){state= {screen:"welcome",lang:state.lang,theme:state.theme,trucks:[newTruck("Forklift 1")],workdayHours:8,shiftCount:1,shiftLengths:[],scheduleConfigKey:null,firstStart:"08:00",shiftStarts:[],breaks:[],intensity:"High",lift:"All"};}
      else if(act==="print"){window.print();return;}
      else if(act==="analyze"){var err=validSetup();if(err){var existing=document.getElementById("formError");if(existing)existing.remove();b.insertAdjacentHTML("afterend",'<span id="formError" class="error">'+esc(err)+'</span>');return;}state.screen="analysis";}
      render();
    });
    app.addEventListener("change",function(e){
      var el=e.target,input=el.dataset.input;if(!input)return;
      if(input==="shift-count")state.shiftCount=Math.max(1,Math.min(24,parseInt(el.value,10)||1));
      else if(input==="workday-hours")state.workdayHours=Math.max(1,Math.min(24,Number(el.value)||8));
      else if(input==="shift-start"){var si=Number(el.dataset.shift);state.shiftStarts[si]=el.value;if(si===0)state.firstStart=el.value;for(var j=si+1;j<state.shiftCount;j++)state.shiftStarts[j]=null;}
      else if(input==="shift-length"){var si=Number(el.dataset.shift);state.shiftLengths[si]=Math.max(.01,Math.min(24,Number(el.value)||.01));for(var k=si+1;k<state.shiftCount;k++)state.shiftStarts[k]=null;}
      else if(input==="break-time"){var si=Number(el.dataset.shift),bi=Number(el.dataset.break);state.breaks[si][bi].start=el.value;}
      else if(input==="break-length"){var si=Number(el.dataset.shift),bi=Number(el.dataset.break);state.breaks[si][bi].length=Math.max(1,Math.min(1440,Number(el.value)||1));}
      render();
    });
    document.querySelectorAll(".language-switch [data-lang]").forEach(function(button){button.addEventListener("click",function(){state.lang=button.dataset.lang;safeStorage.setItem("traknus-lang",state.lang);render();});});
    document.getElementById("themeButton").addEventListener("click",function(){state.theme=state.theme==="dark"?"light":"dark";render();});
    if("serviceWorker" in navigator) window.addEventListener("load",function(){var legacyWorker=new URL("./sw.js",location.href).href;navigator.serviceWorker.getRegistrations().then(function(registrations){registrations.forEach(function(registration){var workers=[registration.active,registration.waiting,registration.installing].filter(Boolean);if(workers.some(function(worker){return worker.scriptURL===legacyWorker;}))registration.unregister();});});if("caches" in window)caches.keys().then(function(keys){keys.filter(function(key){return key.indexOf("traknus-battery-")===0;}).forEach(function(key){caches.delete(key);});});});
    removeLogoBackground();
    var embeddedCatalog=document.getElementById("traknus-catalog");var catalogLoad=embeddedCatalog?Promise.resolve(JSON.parse(embeddedCatalog.textContent)):fetch("catalog.json").then(function(r){if(!r.ok)throw new Error("catalog");return r.json();});catalogLoad.then(function(data){CATALOG=data;render();}).catch(function(){app.innerHTML='<section class="panel"><h2>'+tr("Data katalog belum termuat.","Model catalog did not load.")+'</h2><p class="sub">catalog.json</p></section>';});
  